import { ROLE_LABELS } from "./rules.js";
import type { GameView, Role } from "./types.js";

/** Authored against engine.ts and modules/loups-garous.ts, never generated by an agent. */
export const ROLE_ABILITIES: Record<Role, string> = {
  villager:
    "You have no night ability. During the day, question the villagers, compare their stories, and vote to exile a suspect.",
  werewolf:
    "Each night, choose one living player outside your pack to hunt. You may say let the pack decide to delegate the choice. By day, discuss and vote while keeping your identity secret.",
  seer: "Each night, investigate one other living player you have not investigated before. You privately learn whether that player is a Werewolf. Keep your findings private unless you choose to share them.",
  witch:
    "You have one healing potion and one poison potion for the whole game. At night, you learn the pack's victim while your healing potion is available. You may save that victim, including yourself, or poison another living player, but you cannot poison yourself. You may use both potions in the same night, but not on the same person. Each potion can be used only once. You may also pass without using either potion.",
  hunter:
    "You have no regular night ability. If you are eliminated at night, by a village vote, or through a lover's death, you choose one other living player for a final shot before play continues.",
  cupid:
    "Before the first night, choose two different living players to bind as lovers. You may include yourself. If either lover dies, the other dies immediately. This choice is made only once; after that, you have no night ability.",
};

/** Accept only the server's viewer-scoped view, never the raw Game or NPC roles. */
export function roleExplanation(game: GameView): string {
  const me = game.me;
  const team = me.role === "werewolf" ? "Werewolf" : "village";
  const objective =
    me.role === "werewolf"
      ? "Your team wins when living Werewolves equal or outnumber all other living players."
      : "Your team wins when all Werewolves have been eliminated.";
  const privateDetails: string[] = [];
  if (me.role === "werewolf")
    privateDetails.push(
      !me.alive
        ? "You are eliminated; living pack information is no longer available."
        : me.werewolfTeam?.length
          ? `Your living packmates are ${me.werewolfTeam.join(", ")}.`
          : "You have no living packmates.",
    );
  if (me.role === "witch") {
    privateDetails.push(
      `Your healing potion is ${me.witchHealAvailable ? "available" : "already used"}. Your poison potion is ${me.witchPoisonAvailable ? "available" : "already used"}.`,
    );
    if (me.wolfVictim) privateDetails.push(`Tonight's victim is ${me.wolfVictim}.`);
  }
  if (me.lover)
    privateDetails.push(
      `You are bound to ${me.lover}. If either of you dies, the other dies too. If lovers are on opposite teams, they win together only by being the last two alive.${game.players.find((p) => p.name === me.lover)?.revealedRole ? " Your partner's role is now public." : " Your partner's role has not been disclosed."}`,
    );
  return [
    `Your role is the ${ROLE_LABELS[me.role]}. You are on the ${team} team.`,
    objective,
    ROLE_ABILITIES[me.role],
    ...privateDetails,
    `${me.alive && game.phase !== "over" ? "Your role is private." : "Your role is now public."} You can say Repeat my role, Explain my abilities, or What do I do next at any time.`,
  ].join(" ");
}

export function nextRoleAction(game: GameView, atReveal = false): string {
  const me = game.me;
  if (atReveal)
    return `When this explanation finishes, say I am ready or choose I'm ready to ${game.phase === "prologue" ? "begin the first night" : game.phase === "over" ? "hear the final result" : "continue to your turn"}. To move on before it finishes, say skip role explanation or choose Skip role explanation. ${game.phase === "over" ? "The game is already over; no night action is available." : me.role === "cupid" ? "Your opening action will be to say pair followed by two living player names, for example pair Emma and Lucas." : me.role === "seer" ? "At night, say investigate followed by another living player's name." : me.role === "witch" ? "At night, say save, poison followed by another living player's name, save and poison followed by a different player's name, or pass." : me.role === "werewolf" ? "At night, say hunt followed by a living player's name outside your pack, or let the pack decide." : "At night, say wait for dawn."}`;
  if (game.paused) return "The game is paused. Say resume game when you are ready.";
  if (game.phase === "over")
    return "This game is over. Say start a new game to open another village.";
  if (me.hunterActionPending)
    return "Your final shot is ready. Say shoot followed by another living player's name.";
  if (!me.alive) return "You have been eliminated. Say continue watching to follow the village.";
  if (game.phase === "prologue")
    return "Continue to reveal your role. After the explanation, say I am ready to begin the first night.";
  if (game.phase === "cupid")
    return "Say pair followed by two different living player names, for example pair Emma and Lucas. You may include yourself by saying pair me and a player's name.";
  if (game.phase === "night") {
    if (me.role === "werewolf")
      return "Say hunt followed by a living player's name outside your pack, or let the pack decide.";
    if (me.role === "seer")
      return "Say investigate followed by another living player's name you have not investigated yet, or wait for dawn to pass.";
    if (me.role === "witch")
      return [
        me.witchHealAvailable && me.wolfVictim
          ? `The pack targeted ${me.wolfVictim}. Say save to use your healing potion.`
          : "There is no available healing action right now.",
        me.witchPoisonAvailable
          ? `Say poison followed by another living player's name to use your poison potion.${me.witchHealAvailable && me.wolfVictim ? " To use both available potions, say save and poison followed by a different player's name." : ""}`
          : "Your poison potion has been used.",
        "Say pass to keep your remaining potions.",
      ].join(" ");
    return "You have no action this night. Say wait for dawn to continue.";
  }
  if (game.phase === "day")
    return "Question the village naturally, say hear the villagers, or begin vote.";
  if (game.phase === "vote")
    return "Say vote for followed by another living player's name. Your vote is final.";
  return "Wait for the current player's action, or ask the guide for help.";
}
